.taskListTable{
    padding: 20px;
}
.taskListTable>div.parent_div{
    display: grid;
    grid-template-columns: 50px calc(100% - 560px) 50px 100px 200px 100px 50px;
    align-items: center;
}
.taskListTable>div.parent_div.mobile_div {
grid-template-columns:unset
}
.mobile_div>div>div{
    display: inline-block;
}
.taskListTable>div.parent_div.mobile_div> {
   padding: 5px 5px; 
}
.mobile_div{
    border: 1px solid #eee;
    padding: 10px;
    margin-bottom: 10px;}

    
.taskListTable .parent_div>div{
padding: 10px 5px;
}
.iconsList{
        display: flex;
    align-items: center;
    justify-content: start;
    gap: 10px;
}
.taskListTable .parent_div span{
    background: #e6ffec;
    border: 1px solid #84bf7c;
    border-radius: 31px;
    padding: 2px 10px;
    color: #005726;
    font-size: 13px;
    display: inline-block;
}

.taskListTable .parent_div span[data-status = 'Interval']{
    background: #ffefef;
    border: 1px solid #bf7c7c;
    color: #570000;
}
span.status[data-status]{
    border-radius: 31px;
    padding: 2px 10px;
    font-size: 13px;
}
span.status[data-status = 'WIP']{
    background: #fff6e6;
    border: 1px solid #bfa37c;
    color: #571d00;
}

span.status[data-status = 'Done']{
    background: #eae6ff;
    border: 1px solid #827cbf;
    color: #000a57;
}
.nrf{
        text-align: center;
    color: #b0b0b0;
    font-weight: 600;
}
.ms-mobile{
    display: none;
}
.ms-desk{
    display: none;
}


@media screen and (max-width:776px){
    .ms-mobile{
        display: block;
    }
    
}
@media screen and (min-width:776px){
    .ms-desk{
        display: block;
    }
    
}
